type OrderStatus = 'processing' | 'shipped' | 'delivered' | 'cancelled' | 'returned';
type Order = { id: number; status: OrderStatus; totalCents: number };
type CancelledOrder = { id: number; status: 'cancelled'; cancelReason: string };
type Page<T> = { items: T[]; nextCursor: string | null };

// A fake server: records every request and returns canned data.
const sent: string[] = [];
async function transport(method: string, path: string, body: unknown): Promise<unknown> {
  sent.push(`${method} ${path}${body === undefined ? '' : ' ' + JSON.stringify(body)}`);
  if (path.endsWith('/cancel')) return { id: 1042, status: 'cancelled', cancelReason: 'Changed mind' };
  if (path === '/orders') return { items: [], nextCursor: null };
  return { id: 1042, status: 'processing', totalCents: 18900 };
}

type Routes = {
  'GET /orders/:id': { input: { id: number }; output: Order };
  'GET /orders': { input: { status?: OrderStatus; cursor?: string }; output: Page<Order> };
  'POST /orders/:id/cancel': { input: { id: number; reason: string }; output: CancelledOrder };
};

async function call<R extends keyof Routes>(
  route: R,
  input: Routes[R]['input'],
): Promise<Routes[R]['output']> {
  const [method, template] = route.split(' ');
  // The route map guarantees every :param has a matching input field.
  const values = input as Record<string, unknown>;
  const rest: Record<string, unknown> = { ...values };
  const path = template.replace(/:(\w+)/g, (_, name: string) => {
    delete rest[name];
    return encodeURIComponent(String(values[name]));
  });
  const result = await transport(method, path, method === 'GET' ? undefined : rest);
  return result as Routes[R]['output'];
}

// ---- Type tests (do not edit) ----
async function typeTests() {
  const order = await call('GET /orders/:id', { id: 1042 });
  type T1 = Expect<Equal<typeof order, Order>>;

  const page = await call('GET /orders', { status: 'shipped' });
  type T2 = Expect<Equal<typeof page, Page<Order>>>;

  const cancelled = await call('POST /orders/:id/cancel', { id: 1042, reason: 'Changed mind' });
  type T3 = Expect<Equal<typeof cancelled, CancelledOrder>>;

  // @ts-expect-error: ids are numbers
  await call('GET /orders/:id', { id: '1042' });
  // @ts-expect-error: cancelling needs a reason
  await call('POST /orders/:id/cancel', { id: 1042 });
  // @ts-expect-error: there is no such route
  await call('DELETE /orders/:id', { id: 1042 });
}
